package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.android.controller.*;import org.robolectric.annotation.*;import org.robolectric.shadows.*;import static org.junit.Assert.*;import static org.robolectric.Shadows.shadowOf;

@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class,qualifiers="w360dp-h800dp-mdpi",shadows={ReferenceDesign5150Test.LocalStorage.class}) @LooperMode(LooperMode.Mode.PAUSED) @GraphicsMode(GraphicsMode.Mode.NATIVE)
public class ReferenceDesign5150Test {
 @Implements(Environment.class) public static class LocalStorage extends ShadowEnvironment {@Implementation protected static boolean isExternalStorageManager(){return true;}}
 MainActivity a;ActivityController<MainActivity> controller;
 @Before public void before()throws Exception{
  new FlashDesignTest().before();Application app=RuntimeEnvironment.getApplication();WorkspaceEpoch.value=0;WorkspaceEpoch.restoring=false;app.getSharedPreferences("seeky",0).edit().putBoolean("theme_v2",true).putInt("icon_size",1).putInt("flash_button_size",1).putBoolean("monitor_enabled",false).putBoolean("float_enabled",false).apply();AppUpdates.prefs(app).edit().putBoolean("automatic",false).apply();Environment.getExternalStorageDirectory().mkdirs();ShadowStatFs.registerStats(Environment.getExternalStorageDirectory().getPath(),30000000,6000000,6000000);
  controller=Robolectric.buildActivity(MainActivity.class);a=controller.get();a.setTheme(android.R.style.Theme_Material_NoActionBar);controller.create().start().resume().visible();drain();
 }
 @After public void after()throws Exception{if(controller!=null)controller.pause().stop().destroy();if(a!=null){a.worker.awaitTermination(10,TimeUnit.SECONDS);a.finder.awaitTermination(10,TimeUnit.SECONDS);}}
 void drain()throws Exception{for(int i=0;i<3;i++){a.finder.submit(()->{}).get(15,TimeUnit.SECONDS);a.studies.worker.submit(()->{}).get(15,TimeUnit.SECONDS);a.books.worker.submit(()->{}).get(15,TimeUnit.SECONDS);a.thumbnails.worker.submit(()->{}).get(15,TimeUnit.SECONDS);shadowOf(Looper.getMainLooper()).idle();}}
 void capture(View view,String name,int w,int h)throws Exception{view.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));view.layout(0,0,w,h);Bitmap b=Bitmap.createBitmap(w,h,Bitmap.Config.ARGB_8888);view.draw(new Canvas(b));try(FileOutputStream out=new FileOutputStream(System.getProperty("seeky.screenshot")+"-5150-"+name+".png")){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 View description(View v,String label){if(label.equals(String.valueOf(v.getContentDescription())))return v;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++){View found=description(g.getChildAt(i),label);if(found!=null)return found;}}return null;}
 @Test public void homeAndExplorerUseRealDataWithReferenceStyleAndNoAccountPrompt()throws Exception{
  assertEquals("Início",a.tab);assertTrue(a.shell.getBackground() instanceof BrandSurface);String labels=BooksToolsTest.labels(a.shell);assertTrue(labels.contains("As suas categorias"));assertFalse(labels.contains("Facebook"));Intent launched=shadowOf(a).getNextStartedActivity();assertTrue(launched==null||!launched.getComponent().getClassName().contains("AccountActivity"));capture(a.shell,"inicio",360,800);a.tab="Explorar";a.render();drain();assertTrue(BooksToolsTest.labels(a.shell).contains("Explorar armazenamentos"));capture(a.shell,"explorar",360,800);
 }
 @Test public void homePlusMinusResizeActualCategoryGlyphsAndPersistAtBothBounds()throws Exception{
  View plus=description(a.shell,"Aumentar ícones");assertNotNull(plus);plus.performClick();assertEquals(2,a.iconSize);assertEquals(2,IconSizing.icons(a));assertFalse(description(a.shell,"Aumentar ícones").isEnabled());description(a.shell,"Diminuir ícones").performClick();description(a.shell,"Diminuir ícones").performClick();assertEquals(0,a.iconSize);assertFalse(description(a.shell,"Diminuir ícones").isEnabled());a.changeIcons(-1);assertEquals(0,IconSizing.icons(a));
 }
 @Test public void moreMenuHasSpacedReferenceCardsAndNoSocialAccounts()throws Exception{
  a.moreNavigation();UiPanel panel=UiPanel.open.get(a).iterator().next();String labels=BooksToolsTest.labels(panel.root);assertTrue(labels.contains("Favoritos"));assertTrue(labels.contains("Consultar passagem bíblica"));assertFalse(labels.contains("Facebook"));assertFalse(labels.contains("Conta Google"));capture(panel.root,"mais",360,480);a.studies.settings();for(UiPanel p:UiPanel.open.get(a)){assertFalse(BooksToolsTest.labels(p.root).contains("Google / Facebook"));}
 }
 @Test public void sizingWorksInsideFlashAndTheClosedBubbleUsesTheSavedDiameter()throws Exception{
  ServiceController<QuickSearchService> driver=Robolectric.buildService(QuickSearchService.class).create();QuickSearchService s=driver.get();try{s.bubble();s.expand();FlashPanelView panel=s.panelView;panel.sizeButton.performClick();assertEquals(View.VISIBLE,panel.sizeTools.getVisibility());SizeControl icons=(SizeControl)panel.sizeTools.getChildAt(0),bubble=(SizeControl)panel.sizeTools.getChildAt(1);icons.plus.performClick();bubble.plus.performClick();assertEquals(2,IconSizing.icons(a));assertEquals(2,IconSizing.bubble(a));capture(panel,"flash-ajustes",360,570);s.collapse(null);assertEquals(72,s.params.width);FlashBubbleView v=(FlashBubbleView)s.window;capture(v,"flash-grande",72,72);assertEquals(64,v.circle.getWidth());s.bubble();assertEquals(72,s.params.width);}finally{driver.destroy();}
 }
 @Test public void leavingTheAppClosesTheCatalogueOnlyAfterAllThreeReadersFinish()throws Exception{drain();Catalog counted=a.db;android.database.sqlite.SQLiteDatabase database=counted.getReadableDatabase();CountDownLatch started=new CountDownLatch(3),write=new CountDownLatch(1),find=new CountDownLatch(1),search=new CountDownLatch(1);a.worker.execute(()->{counted.getReadableDatabase();started.countDown();try{write.await(10,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}});a.finder.execute(()->{counted.getReadableDatabase();started.countDown();try{find.await(10,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}});a.searchJobs.submit(g->{counted.getReadableDatabase();started.countDown();try{search.await(10,TimeUnit.SECONDS);}catch(InterruptedException e){Thread.currentThread().interrupt();}});assertTrue(started.await(5,TimeUnit.SECONDS));controller.pause().stop().destroy();controller=null;assertTrue(database.isOpen());write.countDown();assertTrue(a.worker.awaitTermination(5,TimeUnit.SECONDS));assertTrue(database.isOpen());find.countDown();search.countDown();assertTrue(a.finder.awaitTermination(5,TimeUnit.SECONDS));long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(3);while(database.isOpen()&&System.nanoTime()<deadline)Thread.sleep(5);assertFalse(database.isOpen());}
 @Test public void legacyAccountDestinationOnlyOpensLocalBackupAndNeverStartsOAuth(){ActivityController<AccountActivity> c=Robolectric.buildActivity(AccountActivity.class).create();try{Intent intent=shadowOf(c.get()).getNextStartedActivity();assertNotNull(intent);assertEquals(ToolsActivity.class.getName(),intent.getComponent().getClassName());assertNotEquals(Intent.ACTION_VIEW,intent.getAction());assertTrue(c.get().isFinishing());assertFalse(a.getSharedPreferences("cloud",0).getBoolean("auto",true));a.getSharedPreferences("cloud",0).edit().putBoolean("auto",true).apply();CloudJobs.schedule(a);assertNull(((android.app.job.JobScheduler)a.getSystemService(Context.JOB_SCHEDULER_SERVICE)).getPendingJob(CloudJobs.ID));a.getSharedPreferences("cloud",0).edit().putBoolean("auto",false).apply();}finally{c.destroy();}}
 @Test public void fileGlyphsReallyChangeSizeAndLiveFlashRowsUseThePreference(){Catalog.Entry entry=new Catalog.Entry();entry.name="Documento.pdf";entry.mime="application/pdf";entry.uri="content://test/pdf";entry.path="Livros";entry.category="PDF";entry.size=100;FileRowView row=new FileRowView(a,(e,v)->{});IconSizing.set(a,"icon_size",0);row.bind(entry,a.surface,a.text,a.muted,a.accent,true,"");int small=row.icon.getLayoutParams().width;IconSizing.set(a,"icon_size",2);row.resizeIcons();assertTrue(row.icon.getLayoutParams().width>small);FileItemView item=new FileItemView(a,3,2,new FileItemView.Actions(){public void select(Catalog.Entry e){}public void favorite(Catalog.Entry e,View v){}});assertEquals(64,item.icon.getLayoutParams().width);}
 @Test public void libraryGridRetainsCoversPercentagesAndAllReadingActions()throws Exception{
  String[] titles={"O poder da leitura","Organizar o tempo","Aprender todos os dias","Palavras e sabedoria"};int[] progress={0,12,51,100};for(int n=0;n<4;n++){String hash=String.format(java.util.Locale.ROOT,"%064x",n+1);File dir=new File(a.getFilesDir(),"book-covers");dir.mkdirs();File cover=new File(dir,"fixture-"+n+".png");Bitmap image=Bitmap.createBitmap(240,340,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(image);Paint paint=new Paint(3);paint.setShader(new LinearGradient(0,0,240,340,new int[]{0xff1d2158,0xff365db6,0xff971ed3}[n%3],0xff151634,Shader.TileMode.CLAMP));canvas.drawRect(0,0,240,340,paint);paint.setShader(null);paint.setColor(Color.WHITE);paint.setTextSize(22);paint.setTypeface(Typeface.DEFAULT_BOLD);canvas.drawText("SEEKY",22,55,paint);paint.setTextSize(17);canvas.drawText("LIVRO DE ENSAIO",22,220,paint);try(FileOutputStream out=new FileOutputStream(cover)){image.compress(Bitmap.CompressFormat.PNG,100,out);}image.recycle();BookSettings.update(a,hash,p->p.put("cover",cover.getPath()));try(StudyStore store=new StudyStore(a)){store.save("materials",0,StudyStore.values("subject",0,"title",titles[n],"author","Autor de ensaio","name",titles[n]+".pdf","mime","application/pdf","path","/private/fixture.pdf","hash",hash,"bytes",100,"progress",progress[n],"status","A estudar","created",n+1,"updated",n+1));}}
  a.tab="Livros";a.books.mode=1;a.render();drain();assertEquals(4,a.books.books.size());assertEquals(4,BooksToolsTest.count(a.body,BookProgressBadge.class));capture(a.shell,"livros",360,800);int rows=a.books.content.getChildCount();IconSizing.set(a,"icon_size",2);a.books.draw();assertTrue(a.books.content.getChildCount()>rows);a.books.bookMenu(a.books.books.get(0));UiPanel p=UiPanel.open.get(a).iterator().next();assertTrue(BooksToolsTest.labels(p.root).contains("Ler"));assertTrue(BooksToolsTest.labels(p.root).contains("Ouvir"));assertTrue(BooksToolsTest.labels(p.root).contains("Partilhar livro"));
 }
}
